import{_ as o,o as c,c as d,a5 as t}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"严格模式","description":"ES6 的模块自动采用严格模式，不管你有没有在模块头部加上 \\"use strict\\"; 。 严格模式主要有以下限制。 变量必须声明后再使用 函数的参数不能有同名属性，否则报错 不能使用 with 语句 不能对只读属性赋值，否则报错 不能使用前缀 0 表示八进制数，否则报错 不能删。","frontmatter":{"title":"严格模式","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","模块化与工程化"],"description":"ES6 的模块自动采用严格模式，不管你有没有在模块头部加上 \\"use strict\\"; 。 严格模式主要有以下限制。 变量必须声明后再使用 函数的参数不能有同名属性，否则报错 不能使用 with 语句 不能对只读属性赋值，否则报错 不能使用前缀 0 表示八进制数，否则报错 不能删。","sidebarWeight":29,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/12-模块化编程/Module 的语法/严格模式.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/06-模块化与工程化/Module 的语法/严格模式.md","filePath":"posts/JavaScript系统教程/06-模块化与工程化/Module 的语法/严格模式.md"}'),i={name:"posts/JavaScript系统教程/06-模块化与工程化/Module 的语法/严格模式.md"};function l(a,e,s,r,n,p){return c(),d("div",null,[...e[0]||(e[0]=[t('<div><h1 id="严格模式" tabindex="-1">严格模式 <a class="header-anchor" href="#严格模式" aria-label="Permalink to &quot;严格模式&quot;">​</a></h1><blockquote><p>本节目标：理解“严格模式”的核心思路，并能把它用于实际开发或面试表达。 <code>ES6</code> 的模块自动采用严格模式，不管你有没有在模块头部加上<code>&quot;use strict&quot;;</code>。</p></blockquote><p><strong>严格模式主要有以下限制。</strong></p><ul><li>变量必须声明后再使用</li><li>函数的参数不能有同名属性，否则报错</li><li>不能使用<code>with</code>语句</li><li>不能对只读属性赋值，否则报错</li><li>不能使用前缀 <code>0</code> 表示八进制数，否则报错</li><li>不能删除不可删除的属性，否则报错</li><li>不能删除变量<code>delete prop</code>，会报错，只能删除属性<code>delete global[prop]</code></li><li><code>eval</code>不会在它的外层作用域引入变量</li><li><code>eval</code>和<code>arguments</code>不能被重新赋值</li><li><code>arguments</code>不会自动反映函数参数的变化</li><li>不能使用<code>arguments.callee</code></li><li>不能使用<code>arguments.caller</code></li><li>禁止<code>this</code>指向全局对象</li><li>不能使用<code>fn.caller</code>和<code>fn.arguments</code>获取函数调用的堆栈</li><li>增加了保留字（比如<code>protected</code>、<code>static</code>和<code>interface</code>）</li></ul><p>上面这些限制，模块都必须遵守。由于严格模式是 <code>ES5</code> 引入的，不属于 <code>ES6</code>，所以请参阅相关 <code>ES5</code> 书籍，本书不再详细介绍了。</p><p>其中，尤其需要注意<code>this</code>的限制。<code>ES6</code> 模块之中，顶层的<code>this</code>指向<code>undefined</code>，即不应该在顶层代码使用<code>this</code>。</p></div>',1)])])}const S=o(i,[["render",l]]);export{_ as __pageData,S as default};
